import { sql } from "drizzle-orm";
import {
  boolean,
  date,
  index,
  integer,
  jsonb,
  numeric,
  pgEnum,
  pgTable,
  smallint,
  text,
  timestamp,
  uniqueIndex,
  uuid,
} from "drizzle-orm/pg-core";
import type { PlanSnapshot } from "./snapshot.js";
import type { SetTarget } from "./targets.js";

// Conventions (docs/decisions/0009): UUIDv7 ids generated by the client, UTC timestamps,
// soft delete via deleted_at. Same table and column names as the iOS SQLite schema
// (apps/ios/HTSKit/Sources/HTSPersistence/AppDatabase.swift); `pnpm sync:shared` exports
// packages/contracts/db-schema.json and the Swift tests compare both.
const timestamps = {
  createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
  updatedAt: timestamp("updated_at", { withTimezone: true }).notNull().defaultNow(),
  deletedAt: timestamp("deleted_at", { withTimezone: true }),
  /**
   * Server-only: when the server last wrote the row, the cursor of sync pulls (docs/decisions/0026).
   * Not mirrored in SQLite; the schema export skips `server_` columns.
   */
  serverUpdatedAt: timestamp("server_updated_at", { withTimezone: true })
    .notNull()
    .default(sql`date_trunc('milliseconds', now())`),
};

// Root of all user data, so it has no athlete_id of its own.
export const athlete = pgTable("athlete", {
  id: uuid("id").primaryKey(),
  displayName: text("display_name").notNull(),
  defaultRestSeconds: integer("default_rest_seconds").notNull().default(90),
  ...timestamps,
});

const owned = () => ({
  id: uuid("id").primaryKey(),
  athleteId: uuid("athlete_id")
    .notNull()
    .references(() => athlete.id),
});

export const attribute = pgEnum("attribute", [
  "strength",
  "power",
  "conditioning",
  "core",
  "mobility",
]);
export const arcKind = pgEnum("arc_kind", ["normal", "special", "filler"]);
export const arcStatus = pgEnum("arc_status", ["queued", "current", "completed"]);
export const blockKind = pgEnum("block_kind", [
  "activation",
  "strength",
  "combo",
  "chained_combo",
  "fight_round",
  "conditioning",
  "core",
  "mobility",
  "cardio",
]);
export const exerciseUnit = pgEnum("exercise_unit", ["reps", "seconds", "meters", "minutes"]);

/**
 * Temporada: a named sequence of arcs (Jiu-Jitsu, Performance). Arcs unlock in order; only one season
 * is active per athlete (docs/decisions/0029).
 */
export const season = pgTable(
  "season",
  {
    ...owned(),
    name: text("name").notNull(),
    position: integer("position").notNull().default(0),
    active: boolean("active").notNull().default(false),
    ...timestamps,
  },
  (t) => [
    uniqueIndex("season_one_active_idx")
      .on(t.athleteId)
      .where(sql`${t.active} AND ${t.deletedAt} IS NULL`),
  ],
);

/** A phase of the program: N workout templates × weeks. */
export const arc = pgTable(
  "arc",
  {
    ...owned(),
    /** Null for free arcs (Manutenção), which belong to no season. */
    seasonId: uuid("season_id").references(() => season.id),
    name: text("name").notNull(),
    kanji: text("kanji"),
    /** Name of the coach's real program this arc follows. */
    program: text("program"),
    kind: arcKind("kind").notNull().default("normal"),
    /** Null for filler arcs, which have no duration. */
    weeks: smallint("weeks"),
    /** Local calendar date (no time zone). */
    startDate: date("start_date"),
    status: arcStatus("status").notNull().default("queued"),
    position: integer("position").notNull(),
    /** "Recomeçar contagem": sessions before this instant do not count for the arc. */
    countResetAt: timestamp("count_reset_at", { withTimezone: true }),
    ...timestamps,
  },
  (t) => [
    index("arc_season_id_idx").on(t.seasonId),
    // Only one current arc per athlete.
    uniqueIndex("arc_one_current_idx")
      .on(t.athleteId)
      .where(sql`${t.status} = 'current' AND ${t.deletedAt} IS NULL`),
  ],
);

/**
 * The recipe of a workout inside an arc (A · Linha de Frente). Reusing it in another arc copies it
 * (docs/decisions/0015); `source_template_id` keeps the origin.
 */
export const workoutTemplate = pgTable(
  "workout_template",
  {
    ...owned(),
    arcId: uuid("arc_id")
      .notNull()
      .references(() => arc.id),
    sourceTemplateId: uuid("source_template_id"),
    letter: text("letter").notNull(),
    name: text("name").notNull(),
    focus: text("focus"),
    position: integer("position").notNull(),
    ...timestamps,
  },
  (t) => [index("workout_template_arc_id_idx").on(t.arcId)],
);

export const block = pgTable(
  "block",
  {
    ...owned(),
    workoutTemplateId: uuid("workout_template_id")
      .notNull()
      .references(() => workoutTemplate.id),
    kind: blockKind("kind").notNull(),
    /** One or more attributes fed by this block's sets. */
    attributes: jsonb("attributes").$type<(typeof attribute.enumValues)[number][]>().notNull(),
    /** Only for fight rounds (6 to 12 min). */
    durationMinutes: smallint("duration_minutes"),
    position: integer("position").notNull(),
    ...timestamps,
  },
  (t) => [index("block_workout_template_id_idx").on(t.workoutTemplateId)],
);

/** Exercise catalog, free text with normalized names (docs/decisions/0016). */
export const exercise = pgTable(
  "exercise",
  {
    ...owned(),
    name: text("name").notNull(),
    /** Lowercase, no accents, single spaces: "Barra Fixa" and "barra  fixa" are the same exercise. */
    normalizedName: text("normalized_name").notNull(),
    defaultAttribute: attribute("default_attribute"),
    unit: exerciseUnit("unit").notNull().default("reps"),
    perSide: boolean("per_side").notNull().default(false),
    /** How to do it: the coach's YouTube link (#110). */
    videoUrl: text("video_url"),
    ...timestamps,
  },
  (t) => [
    uniqueIndex("exercise_athlete_normalized_name_idx")
      .on(t.athleteId, t.normalizedName)
      .where(sql`${t.deletedAt} IS NULL`),
  ],
);

/** An exercise as prescribed inside a block: sets × target, optional own rest. */
export const prescribedExercise = pgTable(
  "prescribed_exercise",
  {
    ...owned(),
    blockId: uuid("block_id")
      .notNull()
      .references(() => block.id),
    exerciseId: uuid("exercise_id")
      .notNull()
      .references(() => exercise.id),
    /** Sets can be a range ("3 a 4"); equal values mean a fixed count. */
    setsMin: smallint("sets_min").notNull(),
    setsMax: smallint("sets_max").notNull(),
    /** One target for every set, or one per set up to sets_max (docs/decisions/0014). */
    targets: jsonb("targets").$type<SetTarget[]>().notNull(),
    restSeconds: integer("rest_seconds"),
    position: integer("position").notNull(),
    ...timestamps,
  },
  (t) => [
    index("prescribed_exercise_block_id_idx").on(t.blockId),
    index("prescribed_exercise_exercise_id_idx").on(t.exerciseId),
  ],
);

export const sessionStatus = pgEnum("session_status", ["in_progress", "completed"]);

/** Load in kg with two decimals (62.5). numeric, never float (docs/decisions/0009). */
const weightKg = (name: string) => numeric(name, { precision: 6, scale: 2 });

/**
 * One performed workout. Its number ("Treino 5 de 6"), duration, volume, XP and records are derived
 * from the rows, not stored (docs/decisions/0010, 0017).
 */
export const session = pgTable(
  "session",
  {
    ...owned(),
    arcId: uuid("arc_id")
      .notNull()
      .references(() => arc.id),
    workoutTemplateId: uuid("workout_template_id")
      .notNull()
      .references(() => workoutTemplate.id),
    status: sessionStatus("status").notNull().default("in_progress"),
    startedAt: timestamp("started_at", { withTimezone: true }).notNull(),
    finishedAt: timestamp("finished_at", { withTimezone: true }),
    /** The athlete's calendar day when it started, for weekly goals and streaks. */
    localDate: date("local_date").notNull(),
    planSnapshot: jsonb("plan_snapshot").$type<PlanSnapshot>().notNull(),
    ...timestamps,
  },
  (t) => [
    index("session_athlete_started_at_idx").on(t.athleteId, t.startedAt),
    index("session_workout_template_id_idx").on(t.workoutTemplateId),
    // Only one workout in progress at a time.
    uniqueIndex("session_one_in_progress_idx")
      .on(t.athleteId)
      .where(sql`${t.status} = 'in_progress' AND ${t.deletedAt} IS NULL`),
  ],
);

/** One set of a prescribed exercise. Values are in the exercise's unit. */
export const loggedSet = pgTable(
  "logged_set",
  {
    ...owned(),
    sessionId: uuid("session_id")
      .notNull()
      .references(() => session.id),
    prescribedExerciseId: uuid("prescribed_exercise_id")
      .notNull()
      .references(() => prescribedExercise.id),
    /** Catalog exercise, for records and "Anterior" across templates. */
    exerciseId: uuid("exercise_id")
      .notNull()
      .references(() => exercise.id),
    setNumber: smallint("set_number").notNull(),
    weightKg: weightKg("weight_kg"),
    reps: smallint("reps"),
    seconds: integer("seconds"),
    meters: numeric("meters", { precision: 8, scale: 2 }),
    completed: boolean("completed").notNull().default(false),
    completedAt: timestamp("completed_at", { withTimezone: true }),
    ...timestamps,
  },
  (t) => [
    index("logged_set_session_id_idx").on(t.sessionId),
    index("logged_set_exercise_id_idx").on(t.exerciseId),
  ],
);

/** Fight round block: complete rounds instead of sets, plus the load used per exercise. */
export const loggedRound = pgTable(
  "logged_round",
  {
    ...owned(),
    sessionId: uuid("session_id")
      .notNull()
      .references(() => session.id),
    blockId: uuid("block_id")
      .notNull()
      .references(() => block.id),
    roundsCompleted: smallint("rounds_completed").notNull().default(0),
    /** [{ "exerciseId": "...", "weightKg": "24" }], weights as decimal strings. */
    weights: jsonb("weights").$type<{ exerciseId: string; weightKg: string }[]>().notNull(),
    ...timestamps,
  },
  (t) => [index("logged_round_session_id_idx").on(t.sessionId)],
);

export const battleResult = pgEnum("battle_result", ["gold", "silver", "bronze", "participation"]);

/** A Batalha: the competition that closes the season. */
export const battle = pgTable(
  "battle",
  {
    ...owned(),
    seasonId: uuid("season_id").references(() => season.id),
    name: text("name").notNull(),
    /** Local calendar date of the competition. */
    date: date("date").notNull(),
    /** Set after the competition. */
    result: battleResult("result"),
    ...timestamps,
  },
  (t) => [index("battle_athlete_date_idx").on(t.athleteId, t.date)],
);

export type Athlete = typeof athlete.$inferSelect;
export type NewAthlete = typeof athlete.$inferInsert;
